import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.BbQUUm7J.js";const h=JSON.parse('{"title":"CLI Command Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1794940900000}'),o={name:"reference/cli.md"};function l(c,t,n,i,s,u){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="cli-command-reference" tabindex="-1">CLI Command Reference <a class="header-anchor" href="#cli-command-reference" aria-label="Permalink to &quot;CLI Command Reference&quot;">​</a></h1><p>Every command accepts <code>--json</code> where output is structured. Global flags: <code>--env sandbox|live</code>, <code>--api-base &lt;url&gt;</code>, <code>--width &lt;cols&gt;</code>.</p><h2 id="session-account" tabindex="-1">Session &amp; account <a class="header-anchor" href="#session-account" aria-label="Permalink to &quot;Session &amp; account&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>furlpay login [--device|--email &lt;addr&gt;]</code></td><td>Browser device flow (RFC 8628) or headless email OTP</td></tr><tr><td><code>furlpay whoami</code></td><td>Active session, verified email, KYC tier, Safe address</td></tr><tr><td><code>furlpay logout</code></td><td>Revoke the local session cookie</td></tr><tr><td><code>furlpay env sandbox|live</code></td><td>Switch environment</td></tr><tr><td><code>furlpay balance</code></td><td>Token balances across Arbitrum, Base, Optimism, Ethereum</td></tr><tr><td><code>furlpay dashboard</code></td><td>Aggregate dashboard view</td></tr></tbody></table><h2 id="payments" tabindex="-1">Payments <a class="header-anchor" href="#payments" aria-label="Permalink to &quot;Payments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>furlpay pay &#39;@handle&#39; &lt;amt&gt; [USD|USDC|EUR]</code></td><td>A2A transfer — quote-bound, consent-first</td></tr><tr><td><code>furlpay pay --demo</code></td><td>Offline reference preview (zero API calls)</td></tr><tr><td><code>furlpay pay --dry-run &#39;@handle&#39; 10 USD</code></td><td>Real quote, never executes</td></tr><tr><td><code>furlpay send &lt;amt&gt; &lt;0xaddr&gt; --token USDC --chain arbitrum</code></td><td>Raw address transfer</td></tr><tr><td><code>furlpay swap USDT USDC 100</code></td><td>Token swap</td></tr><tr><td><code>furlpay bridge 100 --from eth --to arb</code></td><td>Cross-chain bridge</td></tr></tbody></table><h2 id="hyperliquid-trading" tabindex="-1">Hyperliquid &amp; trading <a class="header-anchor" href="#hyperliquid-trading" aria-label="Permalink to &quot;Hyperliquid &amp; trading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>furlpay hyperliquid status|markets</code></td><td>Validator connectivity / tradeable contracts</td></tr><tr><td><code>furlpay hyperliquid trade --symbol BTC --side buy|sell --size &lt;s&gt; --leverage &lt;l&gt; [--limit &lt;px&gt;]</code></td><td>Signed perp order (LIVE)</td></tr><tr><td><code>furlpay hyperliquid close BTC</code></td><td>Reduce-only market close (LIVE)</td></tr><tr><td><code>furlpay market &lt;SYM&gt; [--slippage bps] [--side buy]</code></td><td>L2 book, depth bands, OFI, micro-price</td></tr><tr><td><code>furlpay account balance|positions|orders</code></td><td>Clearinghouse state</td></tr><tr><td><code>furlpay trading limits --max-single-order &lt;usd&gt; --max-leverage &lt;n&gt;</code></td><td>Pre-trade risk caps</td></tr><tr><td><code>furlpay trading kill-switch --symbol &lt;SYM&gt;</code></td><td>Emergency stop per symbol</td></tr><tr><td><code>furlpay earn hlp stats|deposit &lt;usd&gt;|withdraw &lt;usd&gt;</code></td><td>HLP vault (4-day lockup)</td></tr><tr><td><code>furlpay short mechanisms|signal</code></td><td>Venue status / readiness research (read-only)</td></tr></tbody></table><h2 id="binance" tabindex="-1">Binance <a class="header-anchor" href="#binance" aria-label="Permalink to &quot;Binance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>furlpay binance balances</code></td><td>Spot balances</td></tr><tr><td><code>furlpay binance ticker &lt;SYM&gt;</code> / <code>depth &lt;SYM&gt; --limit n</code></td><td>Market data</td></tr><tr><td><code>furlpay binance spot buy &lt;SYM&gt; --quote &lt;usd&gt;</code> / <code>sell &lt;SYM&gt; --qty &lt;q&gt;</code></td><td>Market orders (agent-trust gated)</td></tr><tr><td><code>furlpay binance open-orders [--symbol &lt;SYM&gt;]</code> / <code>cancel &lt;id&gt; --symbol &lt;SYM&gt;</code></td><td>Order management</td></tr></tbody></table><h2 id="stellar-rwas-escrow" tabindex="-1">Stellar, RWAs &amp; escrow <a class="header-anchor" href="#stellar-rwas-escrow" aria-label="Permalink to &quot;Stellar, RWAs &amp; escrow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>furlpay wallet connect ledger|extension|walletconnect|sep7</code></td><td>Custody options</td></tr><tr><td><code>furlpay wallet import --name &lt;n&gt; [--mnemonic]</code></td><td>Keystore import (stdin only)</td></tr><tr><td><code>furlpay wallet agent-keygen --name &lt;n&gt; --daily-limit &lt;usd&gt; …</code></td><td>Delegated agent policy</td></tr><tr><td><code>furlpay trade limit|market-buy|swap|terminal</code></td><td>SDEX/Soroban (SIMULATED in this build)</td></tr><tr><td><code>furlpay order list|inspect|cancel|cancel-all</code></td><td>Offer management</td></tr><tr><td><code>furlpay rwa list|inspect|kyc</code></td><td>Tokenized securities catalog (SEP-8 never claimed)</td></tr><tr><td><code>furlpay escrow create|fund|start-delivery|proof|release|dispute|status</code></td><td>ETSS local escrow ledger</td></tr></tbody></table><h2 id="oracle-solana-live-read-only" tabindex="-1">Oracle &amp; Solana (live read-only) <a class="header-anchor" href="#oracle-solana-live-read-only" aria-label="Permalink to &quot;Oracle &amp; Solana (live read-only)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>furlpay oracle price &lt;ASSET&gt;</code></td><td>Multi-source USD quote (Coinbase/Kraken/Binance/Jupiter), median + agreement gate — DISAGREEMENT/UNAVAILABLE carry a null price</td></tr><tr><td><code>furlpay oracle sources</code></td><td>Source inventory: endpoints and covered assets (Pyth gateway shown inactive unless configured)</td></tr><tr><td><code>furlpay solana status</code></td><td>Live cluster status from mainnet RPC (epoch, slot, block height)</td></tr><tr><td><code>furlpay solana balance &lt;addr&gt;</code></td><td>Lamport balance via live RPC (base58-validated)</td></tr><tr><td>`furlpay solana price &lt;mint</td><td>alias&gt;`</td></tr><tr><td><code>furlpay solana quote &lt;in&gt; &lt;out&gt; &lt;raw-amount&gt;</code></td><td>Indicative Jupiter route — labeled INDICATIVE, nothing in this build can fill it</td></tr><tr><td><code>furlpay mainnet readiness</code></td><td>Every execution prerequisite, PASS/FAIL/BLOCKED/NOT_VERIFIED — exit 1 = not ready</td></tr><tr><td><code>furlpay mainnet status</code></td><td>Per-surface network/mode/status snapshot (read-only)</td></tr><tr><td><code>furlpay mainnet dry-run &lt;SYM&gt; --side --size</code></td><td>Real risk-engine evaluation of a hypothetical order — never signs, never submits</td></tr></tbody></table><h2 id="verification-diagnostics" tabindex="-1">Verification &amp; diagnostics <a class="header-anchor" href="#verification-diagnostics" aria-label="Permalink to &quot;Verification &amp; diagnostics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>furlpay tx verify &lt;hash&gt; --network mainnet|testnet</code></td><td>Real Horizon lookup with honest semantics</td></tr><tr><td><code>furlpay faucet --address &lt;G...&gt;</code></td><td>Friendbot funding (testnet/futurenet only)</td></tr><tr><td><code>furlpay config validate</code></td><td>Local config structural checks</td></tr><tr><td><code>furlpay doctor</code></td><td>Install/registry/config/connectivity diagnostics</td></tr><tr><td><code>furlpay update [--check]</code></td><td>Self-update (npm)</td></tr><tr><td><code>furlpay mcp --wallet &lt;name&gt;</code></td><td>Start the STDIO MCP server</td></tr></tbody></table><h2 id="x402-forks" tabindex="-1">x402 &amp; forks <a class="header-anchor" href="#x402-forks" aria-label="Permalink to &quot;x402 &amp; forks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>furlpay x402 pay --challenge-header &lt;hdr&gt; --max-cost &lt;usd&gt;</code></td><td>HTTP 402 settlement (SIMULATED)</td></tr><tr><td><code>furlpay fork networks|inspect|replay-check</code></td><td>Fork registry &amp; replay-risk audit (read-only)</td></tr><tr><td><code>furlpay fork simulate|psbt-inspect|opreturn|taint-plan</code></td><td>Review-only sweep artifacts</td></tr></tbody></table><p>Exit codes: <code>0</code> success; <code>1</code> failure, refused, or unknown outcome. Machine-readable diagnostics via <code>--output json</code>.</p>',19)])])}const m=e(o,[["render",l]]);export{h as __pageData,m as default};
